// round 8 checks (offline mode): draft numbers, follow-up box, archive, permanent delete
const {chromium}=require('playwright');const path=require('path');
const ok=(c,m)=>{console.log((c?'PASS ':'FAIL ')+m);if(!c)process.exitCode=1};
(async()=>{const app=path.resolve(process.argv[2]);const b=await chromium.launch();const p=await b.newPage({viewport:{width:1366,height:900}});const errs=[];p.on('pageerror',e=>errs.push(e.message));p.on('dialog',d=>d.accept());
const w=ms=>p.waitForTimeout(ms);const as=async u=>{await p.evaluate(u=>{ME=S.users.find(x=>x.user===u);permBump();rerender()},u);await w(200)};
await p.goto('file://'+app+'#/');await p.waitForFunction(()=>window.__KS_OK,{timeout:30000});await as('admin');
const q0=await p.evaluate(()=>S.qseq);
await p.evaluate(()=>newQuote());await w(400);let id=await p.evaluate(()=>location.hash.split('/').pop());
ok(/^DRF-/.test(id)&&await p.evaluate(()=>S.qseq)===q0,'new quote is a draft without a number ('+id+')');
ok((await p.textContent('h1')).includes('پیش‌نویس'),'draft shows «پیش‌نویس» as its number');
await p.click('#qdel');await w(400);ok(await p.evaluate(id=>!S.quotes[id]&&S.qseq,id)===q0,'draft deleted, no number used');
await p.evaluate(()=>newQuote());await w(400);id=await p.evaluate(()=>location.hash.split('/').pop());
await p.evaluate(id=>{const Q=S.quotes[id];Q.customer={name:'آزمون',mobile:'09121234567'};Q.lines=[{p:'',desc:'پیچ آزمون',q:10,u:'عدد',price:1000,disc:0}];rerender()},id);await w(400);
await p.check('#dfollowOn');await p.fill('#dfollow','پیرو درخواست شمارهٔ ۱۲۳ شرکت نمونه');await w(100);
await p.click('#qsend');await w(500);const nid=await p.evaluate(()=>location.hash.split('/').pop());
ok(!/^DRF/.test(nid)&&nid.endsWith(String(q0+1).padStart(4,'0'))&&await p.evaluate(nid=>S.quotes[nid].status==='sent',nid),'sent quote got the next number '+nid);
await p.goto('file://'+app+'#/doc/pf/'+nid);await w(500);ok((await p.textContent('.docpage')).includes('پیرو درخواست: پیرو درخواست شمارهٔ ۱۲۳'),'follow-up text printed under the parties');
ok(await p.evaluate(()=>{const a=document.querySelector('.dparties'),f=document.querySelector('.dfollow');return a&&f&&a.nextElementSibling===f}),'follow-up box sits right under the seller/buyer boxes');
await as('sales');await p.goto('file://'+app+'#/admin/quote/'+nid);await w(500);
ok(await p.$('#qarch')&&!(await p.$('#qhdel')),'sales manager: can archive, cannot delete');
await p.click('#qarch');await w(300);ok(await p.evaluate(nid=>!!S.quotes[nid].arch,nid),'archived');
await p.goto('file://'+app+'#/admin/quotes');await w(400);ok(!(await p.textContent('#app')).includes(nid),'archived quote hidden from the list');
await p.goto('file://'+app+'#/admin/quotes?f=arch');await w(400);ok((await p.textContent('#app')).includes(nid),'shown under «بایگانی‌شده»');
await as('admin');await p.goto('file://'+app+'#/admin/quote/'+nid);await w(400);await p.click('#qhdel');await w(400);
ok(await p.evaluate(nid=>!S.quotes[nid],nid),'admin deleted it permanently');
const I=await p.evaluate(()=>Object.values(S.invoices).find(I=>I.status==='issued').id);await p.goto('file://'+app+'#/admin/invoice/'+I);await w(400);
await p.click('#ihdel');await w(300);ok(await p.evaluate(I=>!!S.invoices[I],I),'issued invoice cannot be deleted before voiding');
await p.click('#iarch');await w(300);ok(await p.evaluate(I=>!!S.invoices[I].arch,I),'invoice archived');
ok(await p.evaluate(()=>roleOf('sales').perms.includes('sales.invoice.archive')&&!roleOf('r_karma').perms.includes('sales.invoice.archive')),'archive permission in the sales role, not in the sample custom role');
await as('admin');await p.goto('file://'+app+'#/');await w(600);
const pos=await p.evaluate(()=>{const a=document.querySelector('.appbar .hdr-act').getBoundingClientRect(),wr=document.querySelector('.appbar .wrap').getBoundingClientRect();return [Math.round(a.left-wr.left)]});
ok(pos[0]<40,'header actions at the left edge of the header ('+pos+')');
ok(!errs.length,'no JS errors '+errs.slice(0,3));await b.close()})();
